with flagged as (select *, case when lag(started_at) over (partition by customer_id order by started_at, id) is null or started_at > lag(started_at) over (partition by customer_id order by started_at, id) + interval 90 days then 1 else 0 end as is_new_burst from sessions), sessions_sessions as (select *, sum(is_new_burst) over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) as burst_id from flagged) select case when burst_id >= 8 then 'LARGE' else 'SMALL' end as burst_id_tier, max(started_at) as last_seen, sort_array(collect_set(browser)) as browser_list, percentile_approx(burst_id, array(0.25, 0.5, 0.75)) as burst_id_quartiles from sessions_sessions group by case when burst_id >= 8 then 'LARGE' else 'SMALL' end;
